#!/usr/bin/env node
// Generates the public export surface of @tecton-mui/ui from the pinned MUI packages:
//   - packages/ui/src/<Module>/index.ts passthrough re-exports (marked AUTO-GENERATED)
//   - packages/ui/src/index.ts root barrel with explicit, de-duplicated named exports
//   - packages/ui/package.json "exports" map
//   - tooling/compatibility/export-inventory.json (version audit: included/excluded/collisions)
// Hand-written modules (any src/<Dir> without the generated marker) are never overwritten and take
// precedence over passthroughs. `--check` fails if any output is out of date.
import {
  readFileSync,
  writeFileSync,
  readdirSync,
  existsSync,
  mkdirSync,
  rmSync,
  statSync,
} from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import { execFileSync } from 'node:child_process';

const repo = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const ui = join(repo, 'packages/ui');
const src = join(ui, 'src');
const require = createRequire(join(ui, 'package.json'));
const ts = require('typescript');
const CHECK = process.argv.includes('--check');
const MARKER = '// AUTO-GENERATED by tooling/compatibility/generate-exports.mjs';

const pkgDir = (name) => dirname(require.resolve(`${name}/package.json`));
const pkgVersion = (name) =>
  JSON.parse(readFileSync(join(pkgDir(name), 'package.json'), 'utf8')).version;

/** Module directories referenced by a package's root index.d.ts. */
function indexModules(name) {
  const index = readFileSync(join(pkgDir(name), 'index.d.ts'), 'utf8');
  return [
    ...new Set([...index.matchAll(/from "\.\/([A-Za-z0-9_]+)\/index\.js"/g)].map((m) => m[1])),
  ];
}
const hasDefault = (name, mod) =>
  /export \{[^}]*\bas default\b|export \{ default( \}|,)|export default /.test(
    readFileSync(join(pkgDir(name), mod, 'index.d.ts'), 'utf8'),
  );

/** Whether a module directory declares an export named after the module (e.g. SimpleTreeView). */
function exportsNamesake(name, mod) {
  if (!/^[A-Z]/.test(mod)) return false;
  const dir = join(pkgDir(name), mod);
  const index = readFileSync(join(dir, 'index.d.ts'), 'utf8');
  const listed = (text) =>
    [...text.matchAll(/export (?:type )?\{([^}]*)\}/g)].some((m) =>
      m[1]
        .split(',')
        .map((x) => x.trim())
        .includes(mod),
    );
  if (listed(index)) return true;
  // Follow `export * from "./File.js"` one level (only files the public index re-exports).
  return [...index.matchAll(/export \* from "\.\/([^"]+)\.js"/g)].some(([, file]) => {
    const path = join(dir, `${file}.d.ts`);
    if (!existsSync(path)) return false;
    const text = readFileSync(path, 'utf8');
    return new RegExp(`export declare (const|function|class) ${mod}\\b`).test(text) || listed(text);
  });
}

const LAB_EXCLUDED_REASON = {
  LoadingButton: 'deprecated in @mui/lab; use Button `loading` prop',
  TreeView: 'deprecated stub; moved to MUI X Tree View (see SimpleTreeView/RichTreeView)',
  TreeItem: 'deprecated stub; use the MUI X TreeItem',
  useAutocomplete: 'duplicate of @mui/material useAutocomplete',
};
const MATERIAL_EXCLUDED_REASON = {
  styles: 'replaced by the Tecton-preconfigured @tecton-mui/ui/styles',
  Icon: 'replaced by the Tecton Icon component (font-ligature Material Icon not supported)',
};
// AdapterDateFnsV2 targets date-fns v2, which conflicts with the pinned date-fns v4 default.
const DATE_ADAPTERS = ['AdapterDateFns', 'AdapterDayjs', 'AdapterLuxon', 'AdapterMoment'];

const included = [];
const declarationOnly = [];
const excluded = [];
function plan() {
  for (const mod of indexModules('@mui/material')) {
    if (MATERIAL_EXCLUDED_REASON[mod])
      excluded.push({
        package: '@mui/material',
        module: mod,
        reason: MATERIAL_EXCLUDED_REASON[mod],
      });
    else included.push({ package: '@mui/material', module: mod });
  }
  for (const mod of indexModules('@mui/lab')) {
    const implPath = join(pkgDir('@mui/lab'), mod, `${mod}.js`);
    const impl = existsSync(implPath) ? readFileSync(implPath, 'utf8').slice(0, 4000) : '';
    const stub = /was moved from `@mui\/lab`|moved from @mui\/lab/.test(impl);
    if (LAB_EXCLUDED_REASON[mod])
      excluded.push({ package: '@mui/lab', module: mod, reason: LAB_EXCLUDED_REASON[mod] });
    else if (stub)
      excluded.push({
        package: '@mui/lab',
        module: mod,
        reason: 'deprecated stub; moved to MUI X',
      });
    else included.push({ package: '@mui/lab', module: mod });
  }
  for (const mod of indexModules('@mui/x-date-pickers'))
    included.push({ package: '@mui/x-date-pickers', module: mod });
  for (const mod of DATE_ADAPTERS) {
    if (existsSync(join(pkgDir('@mui/x-date-pickers'), mod, 'index.d.ts'))) {
      // Root-exported only for the default adapter; the others need optional peer libraries.
      included.push({
        package: '@mui/x-date-pickers',
        module: mod,
        rootExport: mod === 'AdapterDateFns',
      });
    }
  }
  for (const mod of indexModules('@mui/x-tree-view'))
    included.push({ package: '@mui/x-tree-view', module: mod });
}

// Hand-written public modules (Icon, LocalizationProvider, DataGrid, RichTreeView, range pickers...).
function customModules() {
  return readdirSync(src)
    .filter((d) => statSync(join(src, d)).isDirectory() && !['styles', 'internal'].includes(d))
    .filter((d) => {
      const index = join(src, d, 'index.ts');
      return existsSync(index) && !readFileSync(index, 'utf8').startsWith(MARKER);
    });
}

// Lowercase utility modules (models, hooks, locales...) collide across packages; they are exposed
// through the root barrel only, never as subpaths.
const isSubpathModule = (mod) =>
  /^[A-Z]/.test(mod) || /^use[A-Z]/.test(mod) || ['colors', 'utils', 'transitions'].includes(mod);

const outputs = new Map();
function out(file, content) {
  outputs.set(file, content);
}

function generatePassthroughs(custom) {
  const modules = [];
  for (const entry of included) {
    const { package: pkg, module: mod } = entry;
    const id =
      /^[a-z]/.test(mod) && !isSubpathModule(mod)
        ? `${pkg.replace('@mui/', '').replace(/-/g, '')}_${mod}`
        : mod;
    if (custom.includes(mod)) {
      entry.overriddenBy = `src/${mod}`;
      continue;
    }
    const dir = `internal/passthrough/${id}`;
    const target = isSubpathModule(mod) ? mod : dir;
    const lines = [MARKER, `// Passthrough of ${pkg}/${mod} (v${pkgVersion(pkg)}). Do not edit.`];
    if (hasDefault(pkg, mod)) lines.push(`export { default } from '${pkg}/${mod}';`);
    else if (exportsNamesake(pkg, mod)) {
      // MUI X modules export components by name only; add the conventional default export.
      lines.push(`export { ${mod} as default } from '${pkg}/${mod}';`);
    }
    lines.push(`export * from '${pkg}/${mod}';`, '');
    out(join(src, target, 'index.ts'), lines.join('\n'));
    modules.push({ ...entry, id: target, subpath: isSubpathModule(mod) });
  }
  return modules;
}

function isTypeOnlyAlias(symbol, checker = currentChecker) {
  let current = symbol;
  for (let i = 0; i < 20 && current && current.flags & ts.SymbolFlags.Alias; i++) {
    for (const decl of current.declarations ?? []) {
      if (ts.isExportSpecifier(decl) && (decl.isTypeOnly || decl.parent.parent.isTypeOnly))
        return true;
      if (ts.isImportSpecifier(decl) && (decl.isTypeOnly || decl.parent.parent.isTypeOnly))
        return true;
      if (ts.isExportDeclaration(decl) && decl.isTypeOnly) return true;
    }
    current = checker.getImmediateAliasedSymbol(current);
  }
  return false;
}
let currentChecker;

/** Names a module re-exports only as types through `export type * from` (recursively via `export *`). */
function typeOnlyStarNames(moduleSymbol, checker, seen = new Set()) {
  const names = new Set();
  if (!moduleSymbol || seen.has(moduleSymbol)) return names;
  seen.add(moduleSymbol);
  for (const decl of moduleSymbol.declarations ?? []) {
    const sf = decl.getSourceFile?.();
    if (!sf) continue;
    for (const st of sf.statements) {
      if (!ts.isExportDeclaration(st) || st.exportClause || !st.moduleSpecifier) continue;
      const target = checker.getSymbolAtLocation(st.moduleSpecifier);
      if (!target) continue;
      if (st.isTypeOnly) for (const e of checker.getExportsOfModule(target)) names.add(e.getName());
      else for (const n of typeOnlyStarNames(target, checker, seen)) names.add(n);
    }
  }
  return names;
}

function exportsOf(files) {
  const program = ts.createProgram(files, {
    module: ts.ModuleKind.NodeNext,
    moduleResolution: ts.ModuleResolutionKind.NodeNext,
    jsx: ts.JsxEmit.ReactJSX,
    target: ts.ScriptTarget.ES2022,
    skipLibCheck: true,
    noEmit: true,
    types: [],
  });
  const checker = program.getTypeChecker();
  currentChecker = checker;
  const result = new Map();
  for (const file of files) {
    const sf = program.getSourceFile(file);
    if (!sf) throw new Error(`Cannot load ${file}`);
    const symbol = checker.getSymbolAtLocation(sf);
    const names = { values: [], types: [], hasDefault: false };
    const typeOnlyStars = typeOnlyStarNames(symbol, checker);
    for (const exp of symbol ? checker.getExportsOfModule(symbol) : []) {
      const name = exp.getName();
      if (name === 'default') {
        names.hasDefault = true;
        continue;
      }
      const target = exp.flags & ts.SymbolFlags.Alias ? checker.getAliasedSymbol(exp) : exp;
      if (target.flags & ts.SymbolFlags.Value && !isTypeOnlyAlias(exp) && !typeOnlyStars.has(name))
        names.values.push(name);
      else names.types.push(name);
    }
    result.set(file, names);
  }
  return result;
}

/** Runtime (ESM) export names of the pinned MUI modules, resolved from packages/ui. */
function runtimeExports(specifiers) {
  const probe = join(ui, '.inventory-probe.mjs');
  writeFileSync(
    probe,
    `const specs = ${JSON.stringify(specifiers)};\nconst out = {};\n` +
      `for (const s of specs) { try { out[s] = Object.keys(await import(s)); } catch { out[s] = null; } }\n` +
      `process.stdout.write(JSON.stringify(out));\n`,
  );
  try {
    return JSON.parse(
      execFileSync(process.execPath, [probe], { cwd: ui, maxBuffer: 64 * 1024 * 1024 }).toString(),
    );
  } finally {
    rmSync(probe, { force: true });
  }
}

function generateRoot(modules, custom) {
  // Priority: Tecton styles, hand-written modules, then Core, Lab, X pickers, X tree view.
  const ordered = [
    { id: 'styles', rel: './styles/index.js', subpath: true, defaultName: null },
    ...custom.map((m) => ({ id: m, rel: `./${m}/index.js`, subpath: true, defaultName: m })),
    ...modules
      .filter((m) => m.rootExport !== false)
      .map((m) => ({
        id: m.id,
        rel: `./${m.id}/index.js`,
        defaultName: /^[A-Z]|^use[A-Z]/.test(m.module) ? m.module : null,
      })),
  ];
  // Write passthroughs to disk temporarily so the checker can resolve them.
  for (const [file, content] of outputs) {
    mkdirSync(dirname(file), { recursive: true });
    if (!existsSync(file) || readFileSync(file, 'utf8') !== content) {
      if (CHECK) continue;
      writeFileSync(file, content);
    }
  }
  const files = ordered.map((m) => join(src, m.rel.replace(/\.js$/, '.ts')));
  const exp = exportsOf(files);
  // Declarations occasionally list values the runtime module does not export (e.g. `BackdropRoot`).
  // Explicit ESM re-exports of those would throw at link time, so drop and record them.
  const rootModules = modules.filter((m) => m.rootExport !== false);
  const runtime = runtimeExports(rootModules.map((m) => `${m.package}/${m.module}`));
  const unloadable = Object.entries(runtime)
    .filter(([, v]) => v === null)
    .map(([k]) => k);
  if (unloadable.length) throw new Error(`Cannot load runtime modules: ${unloadable.join(', ')}`);
  const runtimeById = new Map(
    rootModules.map((m) => [m.id, new Set(runtime[`${m.package}/${m.module}`])]),
  );
  ordered.forEach((m, i) => {
    const keys = runtimeById.get(m.id);
    if (!keys) return;
    const names = exp.get(files[i]);
    names.values = names.values.filter((n) => {
      if (keys.has(n)) return true;
      declarationOnly.push({ module: m.id, name: n });
      return false;
    });
  });
  const taken = new Map();
  const collisions = [];
  const blocks = [
    MARKER,
    '// Root barrel. Explicit named re-exports keep the surface reviewable and tree-shakeable.',
    '',
  ];
  ordered.forEach((m, i) => {
    const names = exp.get(files[i]);
    const claim = (name) => {
      if (taken.has(name)) {
        if (taken.get(name) !== m.id)
          collisions.push({ name, kept: taken.get(name), dropped: m.id });
        return false;
      }
      taken.set(name, m.id);
      return true;
    };
    const values = [];
    if (names.hasDefault && m.defaultName && claim(m.defaultName))
      values.push(`default as ${m.defaultName}`);
    values.push(...names.values.filter(claim).sort());
    const types = names.types.filter(claim).sort();
    if (values.length) blocks.push(`export { ${values.join(', ')} } from '${m.rel}';`);
    if (types.length) blocks.push(`export type { ${types.join(', ')} } from '${m.rel}';`);
  });
  out(join(src, 'index.ts'), blocks.join('\n') + '\n');
  return collisions;
}

function generatePackageExports(modules, custom) {
  const pkgPath = join(ui, 'package.json');
  const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
  const entry = (p) => ({
    '@tecton-mui/source': `./src/${p}/index.ts`,
    types: `./dist/${p}/index.d.ts`,
    default: `./dist/${p}/index.js`,
  });
  const exportsMap = {
    '.': {
      '@tecton-mui/source': './src/index.ts',
      types: './dist/index.d.ts',
      default: './dist/index.js',
    },
    './styles': entry('styles'),
    './styles/global.css': './dist/styles/global.css',
    './styles/components.css': './dist/styles/components.css',
    './styles/tokens.css': './dist/styles/tokens.css',
    './styles/fonts.css': './dist/styles/fonts.css',
    './styles/icons.css': './dist/styles/icons.css',
  };
  const subpaths = [...custom, ...modules.filter((m) => m.subpath).map((m) => m.id)].sort();
  for (const p of subpaths) exportsMap[`./${p}`] = entry(p);
  exportsMap['./package.json'] = './package.json';
  pkg.main = './dist/index.js';
  pkg.types = './dist/index.d.ts';
  pkg.exports = exportsMap;
  out(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
  return subpaths;
}

plan();
const custom = customModules();
const modules = generatePassthroughs(custom);
const collisions = generateRoot(modules, custom);
const subpaths = generatePackageExports(modules, custom);
const inventory = {
  $comment: 'Generated by `pnpm inventory`. Review changes to this file in MUI upgrade PRs.',
  versions: Object.fromEntries(
    [
      '@mui/material',
      '@mui/lab',
      '@mui/system',
      '@mui/x-data-grid',
      '@mui/x-date-pickers',
      '@mui/x-tree-view',
    ].map((p) => [p, pkgVersion(p)]),
  ),
  customModules: custom,
  subpaths,
  included: included.map(({ package: p, module, overriddenBy }) => ({
    package: p,
    module,
    ...(overriddenBy ? { overriddenBy } : {}),
  })),
  excluded,
  rootCollisions: collisions,
  declarationOnlyValues: declarationOnly,
};
out(
  join(repo, 'tooling/compatibility/export-inventory.json'),
  JSON.stringify(inventory, null, 2) + '\n',
);

// Remove stale generated passthroughs.
const expected = new Set([...outputs.keys()]);
const stale = [];
const scan = (dir) => {
  if (!existsSync(dir)) return;
  for (const d of readdirSync(dir)) {
    const index = join(dir, d, 'index.ts');
    if (existsSync(index) && readFileSync(index, 'utf8').startsWith(MARKER) && !expected.has(index))
      stale.push(join(dir, d));
  }
};
scan(src);
scan(join(src, 'internal/passthrough'));

if (CHECK) {
  const diffs = [...outputs]
    .filter(([f, c]) => !existsSync(f) || readFileSync(f, 'utf8') !== c)
    .map(([f]) => f);
  if (diffs.length || stale.length) {
    console.error(
      'Export inventory is out of date. Run `pnpm inventory`.\n' + [...diffs, ...stale].join('\n'),
    );
    process.exit(1);
  }
  console.log('Export inventory up to date.');
} else {
  for (const dir of stale) rmSync(dir, { recursive: true, force: true });
  for (const [file, content] of outputs) {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, content);
  }
  console.log(
    `Generated ${modules.length} passthrough modules, ${custom.length} custom, ${subpaths.length} subpaths, ${collisions.length} root collisions.`,
  );
}
